1	// credit 是本地课程学分与免修的命令行程序。
2	//
3	// 用法：credit -f 记录文件 <子命令> [参数...]
4	//
5	// 学生与课程：
6	//
7	//	student <编号>                              登记学生（编号唯一）
8	//	course <编号> <名称...> <正整数学分>          登记课程（初始开放）
9	//	course-close <编号>                          停开课程
10	//	course-open <编号>                           恢复开放课程
11	//	list-courses                                列出全部课程及状态
12	//
13	// 课程要求（编号在学生名下唯一）：
14	//
15	//	req <学生> <要求编号> <课程编号>              为学生登记课程要求
16	//
17	// 修读（编号在学生名下唯一）：
18	//
19	//	enroll <学生> <要求编号> <学期> <修读编号>    选课登记
20	//	pass   <学生> <修读编号>                      提交“通过”
21	//	fail   <学生> <修读编号>                      提交“未通过”
22	//
23	// 免修（编号在学生名下唯一）：
24	//
25	//	waiver        <学生> <要求编号> <免修编号> <依据...>  提交免修申请
26	//	revoke-waiver <学生> <免修编号> [原因...]            撤销有效免修
27	//
28	// 核对与查询：
29	//
30	//	check <学生>                                 按学生核对学分
31	//	show  <学生>                                 查看学生的要求、修读与免修历史
32	//
33	// 记录文件不存在时从空记录开始；文件无法读取或内容损坏时立即报错，
34	// 不会把它当作空记录覆盖。
35	package main
36	
37	import (
38		"errors"
39		"flag"
40		"fmt"
41		"io"
42		"os"
43		"strconv"
44		"strings"
45	
46		"github.com/descikazuyq/credit-record/credit"
47	)
48	
49	// 退出码：0 成功；1 业务规则被拒绝；2 记录文件错误。
50	const (
51		exitOK       = 0
52		exitRejected = 1
53		exitFile     = 2
54	)
55	
56	func main() {
57		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
58	}
59	
60	func run(args []string, stdout, stderr io.Writer) int {
61		fs := flag.NewFlagSet("credit", flag.ContinueOnError)
62		fs.SetOutput(stderr)
63		fs.Usage = func() {
64			fmt.Fprintln(stderr, "用法：credit -f 记录文件 <子命令> [参数...]")
65			fmt.Fprintln(stderr, "子命令：student course course-close course-open list-courses")
66			fmt.Fprintln(stderr, "        req enroll pass fail waiver revoke-waiver check show")
67			fmt.Fprintln(stderr, "详情见 credit -h")
68		}
69		file := fs.String("f", "", "记录文件路径（必需）")
70		if err := fs.Parse(args); err != nil {
71			return exitRejected
72		}
73		if strings.TrimSpace(*file) == "" {
74			fmt.Fprintln(stderr, "错误：必须用 -f 指定记录文件")
75			fs.Usage()
76			return exitRejected
77		}
78		rest := fs.Args()
79		if len(rest) == 0 {
80			fmt.Fprintln(stderr, "错误：缺少子命令")
81			fs.Usage()
82			return exitRejected
83		}
84	
85		store, existed, err := credit.Load(*file)
86		if err != nil {
87			fmt.Fprintf(stderr, "错误：%v\n", err)
88			return exitFile
89		}
90	
91		cmd, cmdArgs := rest[0], rest[1:]
92		code, err := dispatch(store, cmd, cmdArgs, stdout)
93		if err != nil {
94			fmt.Fprintf(stderr, "错误：%v\n", err)
95		}
96	
97		// 只有真正发生变更才落盘：只读核对、纯幂等重复、被拒绝而未写入数据的
98		// 请求都不改动文件，也不会为一次查询凭空创建空文件。被拒绝的免修申请
99		// 已写入免修历史（store 标记为已变更），仍会保存。损坏文件在 Load 阶段
100		// 就已返回，绝不会走到这里覆盖原文件。
101		if store.Dirty() {
102			if saveErr := store.Save(*file); saveErr != nil {
103				fmt.Fprintf(stderr, "错误：保存记录文件失败：%v\n", saveErr)
104				return exitFile
105			}
106			if !existed {
107				fmt.Fprintf(stdout, "（记录文件 %s 不存在，已从空记录开始并创建）\n", *file)
108			}
109		}
110		return code
111	}
112	
113	func dispatch(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
114		switch cmd {
115		case "student":
116			return cmdStudent(s, args, out)
117		case "course":
118			return cmdCourse(s, args, out)
119		case "course-close", "course-open":
120			return cmdCourseToggle(s, cmd, args, out)
121		case "list-courses":
122			return cmdListCourses(s, out)
123		case "req":
124			return cmdReq(s, args, out)
125		case "enroll":
126			return cmdEnroll(s, args, out)
127		case "pass", "fail":
128			return cmdResult(s, cmd, args, out)
129		case "waiver":
130			return cmdWaiver(s, args, out)
131		case "revoke-waiver":
132			return cmdRevoke(s, args, out)
133		case "check":
134			return cmdCheck(s, args, out)
135		case "show":
136			return cmdShow(s, args, out)
137		default:
138			return exitRejected, fmt.Errorf("未知子命令 %q", cmd)
139		}
140	}
141	
142	func cmdStudent(s *credit.Store, args []string, out io.Writer) (int, error) {
143		if len(args) != 1 {
144			return exitRejected, errors.New("用法：student <编号>")
145		}
146		st, action, err := s.AddStudent(args[0])
147		if err != nil {
148			return exitRejected, err
149		}
150		if action == credit.ActionCreated {
151			fmt.Fprintf(out, "已登记学生 %s\n", st.ID)
152		} else {
153			fmt.Fprintf(out, "学生 %s 已存在，返回原记录\n", st.ID)
154		}
155		return exitOK, nil
156	}
157	
158	func cmdCourse(s *credit.Store, args []string, out io.Writer) (int, error) {
159		if len(args) < 3 {
160			return exitRejected, errors.New("用法：course <编号> <名称...> <正整数学分>")
161		}
162		id := args[0]
163		creditN, err := strconv.Atoi(strings.TrimSpace(args[len(args)-1]))
164		if err != nil {
165			return exitRejected, fmt.Errorf("学分必须是正整数：%q", args[len(args)-1])
166		}
167		name := strings.Join(args[1:len(args)-1], " ")
168		c, action, err := s.AddCourse(id, name, creditN)
169		if err != nil {
170			return exitRejected, err
171		}
172		switch action {
173		case credit.ActionCreated:
174			fmt.Fprintf(out, "已登记课程 %s《%s》%d 学分，状态：开放\n", c.ID, c.Name, c.Credit)
175		case credit.ActionUpdated:
176			fmt.Fprintf(out, "课程 %s 尚未被要求引用，已更新为《%s》%d 学分（状态保持：%s）\n",
177				c.ID, c.Name, c.Credit, openText(c.Open))
178		default:
179			fmt.Fprintf(out, "课程 %s 已存在且内容一致，返回原记录（状态保持：%s）\n",
180				c.ID, openText(c.Open))
181		}
182		return exitOK, nil
183	}
184	
185	func cmdCourseToggle(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
186		if len(args) != 1 {
187			return exitRejected, fmt.Errorf("用法：%s <编号>", cmd)
188		}
189		open := cmd == "course-open"
190		c, err := s.SetCourseOpen(args[0], open)
191		if err != nil {
192			return exitRejected, err
193		}
194		fmt.Fprintf(out, "课程 %s《%s》状态：%s\n", c.ID, c.Name, openText(c.Open))
195		return exitOK, nil
196	}
197	
198	func cmdListCourses(s *credit.Store, out io.Writer) (int, error) {
199		courses := s.Courses()
200		if len(courses) == 0 {
201			fmt.Fprintln(out, "（尚无课程）")
202			return exitOK, nil
203		}
204		for _, c := range courses {
205			fmt.Fprintf(out, "课程 %s《%s》%d 学分，状态：%s\n", c.ID, c.Name, c.Credit, openText(c.Open))
206		}
207		return exitOK, nil
208	}
209	
210	func cmdReq(s *credit.Store, args []string, out io.Writer) (int, error) {
211		if len(args) != 3 {
212			return exitRejected, errors.New("用法：req <学生> <要求编号> <课程编号>")
213		}
214		r, action, err := s.AddRequirement(args[0], args[1], args[2])
215		if err != nil {
216			return exitRejected, err
217		}
218		if action == credit.ActionCreated {
219			fmt.Fprintf(out, "已为学生 %s 登记要求 %s，指向课程 %s\n", r.StudentID, r.ID, r.CourseID)
220		} else {
221			fmt.Fprintf(out, "学生 %s 的要求 %s 已存在且内容一致，返回原记录\n", r.StudentID, r.ID)
222		}
223		return exitOK, nil
224	}
225	
226	func cmdEnroll(s *credit.Store, args []string, out io.Writer) (int, error) {
227		if len(args) != 4 {
228			return exitRejected, errors.New("用法：enroll <学生> <要求编号> <学期> <修读编号>")
229		}
230		e, action, err := s.AddEnrollment(args[0], args[1], args[2], args[3])
231		if err != nil {
232			return exitRejected, err
233		}
234		if action == credit.ActionCreated {
235			fmt.Fprintf(out, "已登记修读 %s：学生 %s，要求 %s，学期 %s，状态：选课\n",
236				e.ID, e.StudentID, e.ReqID, e.Term)
237		} else {
238			fmt.Fprintf(out, "修读 %s 已存在且内容一致，返回原记录（状态：%s）\n",
239				e.ID, zhText(e.Result))
240		}
241		return exitOK, nil
242	}
243	
244	func cmdResult(s *credit.Store, cmd string, args []string, out io.Writer) (int, error) {
245		if len(args) != 2 {
246			return exitRejected, fmt.Errorf("用法：%s <学生> <修读编号>", cmd)
247		}
248		result := credit.Passed
249		if cmd == "fail" {
250			result = credit.Failed
251		}
252		e, changed, err := s.SubmitResult(args[0], args[1], result)
253		if err != nil {
254			return exitRejected, err
255		}
256		if changed {
257			fmt.Fprintf(out, "修读 %s 结果已提交：%s\n", e.ID, zhText(e.Result))
258		} else {
259			fmt.Fprintf(out, "修读 %s 已提交过相同结果“%s”，返回原记录，不重复计学分\n",
260				e.ID, zhText(e.Result))
261		}
262		return exitOK, nil
263	}
264	
265	func cmdWaiver(s *credit.Store, args []string, out io.Writer) (int, error) {
266		if len(args) < 4 {
267			return exitRejected, errors.New("用法：waiver <学生> <要求编号> <免修编号> <依据...>")
268		}
269		student, reqID, waiverID := args[0], args[1], args[2]
270		basis := strings.Join(args[3:], " ")
271		w, action, err := s.ApplyWaiver(student, reqID, waiverID, basis)
272		if err != nil {
273			// 同编号换内容等冲突：不新增记录。
274			return exitRejected, err
275		}
276		if action == credit.ActionExisted {
277			fmt.Fprintf(out, "免修 %s 已提交过且内容一致，返回原申请，状态：%s\n",
278				w.ID, waiverText(w.Status))
279			return exitOK, nil
280		}
281		if w.Status == credit.WaiverApproved {
282			fmt.Fprintf(out, "免修 %s 有效：学生 %s 的要求 %s 凭依据 %q 满足，获得课程学分\n",
283				w.ID, w.StudentID, w.ReqID, w.Basis)
284			return exitOK, nil
285		}
286		// 被拒绝：申请内容与原因已记入该学生免修历史。
287		fmt.Fprintf(out, "免修申请 %s 已拒绝（已记入学生 %s 的免修历史）：%s\n",
288			w.ID, w.StudentID, w.Reason)
289		return exitRejected, nil
290	}
291	
292	func cmdRevoke(s *credit.Store, args []string, out io.Writer) (int, error) {
293		if len(args) < 2 {
294			return exitRejected, errors.New("用法：revoke-waiver <学生> <免修编号> [原因...]")
295		}
296		reason := strings.Join(args[2:], " ")
297		w, changed, err := s.RevokeWaiver(args[0], args[1], reason)
298		if err != nil {
299			return exitRejected, err
300		}
301		if changed {
302			fmt.Fprintf(out, "免修 %s 已撤销，原依据 %q 保留在免修历史；要求按修读情况重新判定\n",
303				w.ID, w.Basis)
304		} else {
305			fmt.Fprintf(out, "免修 %s 已是撤销状态，重复撤销不改变结果（原依据 %q 保留）\n",
306				w.ID, w.Basis)
307		}
308		return exitOK, nil
309	}
310	
311	func cmdCheck(s *credit.Store, args []string, out io.Writer) (int, error) {
312		if len(args) != 1 {
313			return exitRejected, errors.New("用法：check <学生>")
314		}
315		rep := s.CheckStudent(args[0])
316		if !rep.Found {
317			// 没有记录的学生：明确的不存在结果，且不写任何数据。
318			return exitRejected, fmt.Errorf("%s", rep.String())
319		}
320		fmt.Fprint(out, rep.String())
321		return exitOK, nil
322	}
323	
324	func cmdShow(s *credit.Store, args []string, out io.Writer) (int, error) {
325		if len(args) != 1 {
326			return exitRejected, errors.New("用法：show <学生>")
327		}
328		student := args[0]
329		if s.Student(student) == nil {
330			return exitRejected, fmt.Errorf("学生 %s 不存在，没有任何记录", student)
331		}
332		fmt.Fprintf(out, "学生 %s\n", student)
333		reqs := s.Requirements(student)
334		if len(reqs) == 0 {
335			fmt.Fprintln(out, "课程要求：（无）")
336		}
337		for _, r := range reqs {
338			c := s.Course(r.CourseID)
339			fmt.Fprintf(out, "要求 %s -> 课程 %s", r.ID, r.CourseID)
340			if c != nil {
341				fmt.Fprintf(out, "《%s》%d 学分", c.Name, c.Credit)
342			}
343			fmt.Fprintln(out)
344		}
345		enrs := s.Enrollments(student)
346		if len(enrs) == 0 {
347			fmt.Fprintln(out, "修读：（无）")
348		}
349		for _, e := range enrs {
350			fmt.Fprintf(out, "修读 %s：要求 %s，学期 %s，结果：%s\n",
351				e.ID, e.ReqID, e.Term, zhText(e.Result))
352		}
353		ws := s.Waivers(student)
354		if len(ws) == 0 {
355			fmt.Fprintln(out, "免修历史：（无）")
356		}
357		for _, w := range ws {
358			line := fmt.Sprintf("免修 %s：要求 %s，依据 %q，状态：%s",
359				w.ID, w.ReqID, w.Basis, waiverText(w.Status))
360			if w.Reason != "" {
361				line += "（" + w.Reason + "）"
362			}
363			fmt.Fprintln(out, line)
364		}
365		return exitOK, nil
366	}
367	
368	func openText(open bool) string {
369		if open {
370			return "开放"
371		}
372		return "停开"
373	}
374	
375	func zhText(r credit.Result) string {
376		switch r {
377		case credit.Passed:
378			return "通过"
379		case credit.Failed:
380			return "未通过"
381		default:
382			return "选课"
383		}
384	}
385	
386	func waiverText(st credit.WaiverStatus) string {
387		switch st {
388		case credit.WaiverApproved:
389			return "有效"
390		case credit.WaiverRejected:
391			return "已拒绝"
392		case credit.WaiverRevoked:
393			return "已撤销"
394		default:
395			return string(st)
396		}
397	}
