set -e
go build -o /tmp/credit ./cmd/credit

echo "=== 1. 首次登记，父目录不存在：stdout 必须为空，退出码 2，不创建文件 ==="
rm -rf /tmp/nodir
set +e
out=$(/tmp/credit -f /tmp/nodir/missing/r.json student s1 2>/tmp/err1); code=$?
set -e
echo "stdout=[$out]"; echo "stderr=[$(cat /tmp/err1)]"; echo "exit=$code"
[ -z "$out" ] || { echo FAIL_STDOUT; exit 1; }
[ "$code" = 2 ] || { echo FAIL_CODE; exit 1; }
grep -q "保存记录文件 /tmp/nodir/missing/r.json 失败" /tmp/err1 || { echo FAIL_ERRMSG; exit 1; }
grep -q "从空记录" /tmp/err1 && { echo FAIL_HINT_IN_ERR; exit 1; }
[ ! -e /tmp/nodir/missing/r.json ] || { echo FAIL_FILE_CREATED; exit 1; }
echo OK1

echo "=== 2. 修改已有记录，目录只读：stdout 空，原文件内容保留 ==="
d=$(mktemp -d)
f="$d/r.json"
/tmp/credit -f "$f" student s1 >/dev/null
orig=$(cat "$f")
chmod 555 "$d"
set +e
out=$(/tmp/credit -f "$f" student s2 2>/tmp/err2); code=$?
set -e
chmod 755 "$d"
echo "stdout=[$out]"; echo "stderr=[$(cat /tmp/err2)]"; echo "exit=$code"
[ -z "$out" ] || { echo FAIL_STDOUT2; exit 1; }
[ "$code" = 2 ] || { echo FAIL_CODE2; exit 1; }
grep -q "保存记录文件 $f 失败" /tmp/err2 || { echo FAIL_ERRMSG2; exit 1; }
[ "$(cat "$f")" = "$orig" ] || { echo FAIL_KEEP; exit 1; }
grep -q s2 "$f" && { echo FAIL_S2_PERSISTED; exit 1; }
echo OK2

